'use strict';

const _omit = require('lodash/omit');
const stringify = require('../stringify');

/**
 * Стрим для yandex-logger, позволяющий логировать в Yandex.Deploy.
 *
 * @param {YandexLoggerDeployStreamConfig} config
 * @returns {Writable}
 */
module.exports = config => {
    config = config || {};

    let stream = config.stream || process.stdout;
    let excludeFields = config.excludeFields || [];

    /**
     * Qloud-формат позволяет использовать WARN и WARNING для параметра levelStr,
     * но в интерфейсе Yandex.Deploy для фильтрации используется именно WARNING.
     */
    const levelStrByLevelName = {
        WARN: 'WARNING',
    };

    return {
        /**
         * @param {Object} record
         * @returns {undefined}
         */
        write(record) {
            let fields = record;

            if (excludeFields.length > 0) {
                fields = _omit(fields, excludeFields);
            }

            let obj = {
                msg: record.msg,
                stackTrace: record.err && record.err.stack,
                level: record.levelName,
                levelStr: levelStrByLevelName[record.levelName] || record.levelName,
                loggerName: 'yandex-logger',
                request_id: record.requestId,
                user_id: record.userId,
                span_id: record.spanId,
                trace_id: record.traceId,
                '@fields': fields,
            };

            stream.write(stringify(obj) + '\n');
        },
    };
};

/**
 * @typedef {Object} YandexLoggerDeployStreamConfig
 * @property {String} [stream] - Writable stream, например, process.stdout
 * @property {String[]} [excludeFields] - Поля, которые нужно исключить из логов
 */
